const CHANNEL_DEAD_CONFIRMATIONS: u32 = 2;

#[derive(Default)]
struct DeadConfirm {
    streak: u32,
}
impl DeadConfirm {
    /// 收到一次自检结论。返回 true ⇔ **连续** [`CHANNEL_DEAD_CONFIRMATIONS`] 次判死。
    /// 判定为"死"之后立刻清零:一次触发只对应一次重连(重连自己会重新排程)。
    fn observe(&mut self, verdict: ChannelVerdict) -> bool {
        if verdict != ChannelVerdict::Dead {
            self.streak = 0;
            return false;
        }
        self.streak += 1;
        if self.streak >= CHANNEL_DEAD_CONFIRMATIONS {
            self.streak = 0;
            true
        } else {
            false
        }
    }
    fn reset(&mut self) { self.streak = 0; }
}
```
