pub(crate) fn parse_unix_has_socket(text: &str, socket_name: &str) -> Option<bool> {
    let mut rows = 0usize;
    for line in text.lines() {
        let mut fields = line.split_whitespace();
        let Some(_num) = fields.next() else { continue };
        // 头行 "Num RefCount ..." 也是非空行,但它没有第 8 段(Path),不影响计数
        rows += 1;
        if line.split_whitespace().any(|f| f.trim_start_matches('@') == socket_name) {
            return Some(true);
        }
    }
    if rows == 0 { None } else { Some(false) }
}
