fn poll_channel_watch(&mut self) {
    let Some(rx) = self.channel_rx.as_ref() else { return };
    let probe = match rx.try_recv() {
        Ok(p) => p,
        Err(Empty) => return,
        Err(Disconnected) => { self.channel_rx = None; return }
    };
    self.channel_rx = None;
    self.channel_probed_at = Some(Instant::now());
    // 只在结论变化时记一条(不许每 2 秒刷一行)
    if self.channel_verdict_prev != Some(probe.verdict) {
        match probe.verdict {
            adb::ChannelVerdict::Alive => self.log(format!("控制通道存活自检: 设备端在({})", probe.evidence)),
            adb::ChannelVerdict::Dead => { self.log(format!("控制通道存活自检: 设备端 socket 已消失({})", probe.evidence)); crate::diag_warn!("app", "控制通道存活自检判死: {}", probe.evidence); }
            adb::ChannelVerdict::Unknown => self.log(format!("控制通道存活自检: 未知({})", probe.evidence)),
        }
        self.channel_verdict_prev = Some(probe.verdict);
    }
    let dead = probe.verdict == adb::ChannelVerdict::Dead;
    self.channel_probe = Some(probe);
    if !dead { self.channel_dead_confirm.reset(); return; }
    // 连续两次确认才动手:单次判死可能只是 adb 一抖/设备端正在重启
    if self.channel_dead_confirm.observe(adb::ChannelVerdict::Dead)
        && self.reconnect_armed
        && !self.connect_rx.is_some()
    {
        self.restart_control_channel("存活自检连续两次确认设备端 socket 已消失");
    }
}
```
