/// 时返回 `None` —— 那是**别人的**通道还在,不能拿来证明我们这条活着。
pub(crate) fn parse_ps_pad_server(text: &str, scid: u32) -> Option<bool> {
    const PAD_JAR: &str = "scrcpy-server-pad.jar";
