/// 记下最近一条 server 侧错误(截断到 300 字符,避免整页堆栈占满界面)。
pub fn note_server_error(line: &str) {
    let clipped: String = line.trim().chars().take(300).collect();
    if let Ok(mut slot) = SERVER_LAST_ERROR.lock() {
