    /// 重启控制通道:**关掉旧的 → 复用既有的启动+连接路径**。
    ///
    /// 自动(存活自检连续判死)与手动([强制重连控制通道])共用这一条,不另写一套
    /// 启动逻辑。收尾也走既有那条路:`connect_control` 先把 `shared.control` 清成
    /// None(引擎据此清空本地幻影触点),连上后再变回 Some(引擎按当前按键真值
    /// 重建触点)—— 这就是 engine.rs 里判"由断到通"的同一对边沿。
    ///
    /// 返回 false = 没发起(已有一轮连接在途 / 没选设备),原因已写进日志。
    fn restart_control_channel(&mut self, reason: &str) -> bool {
        if self.connect_rx.is_some() {
            self.log(format!(
                "控制通道重启被跳过(已有一轮连接在进行中):{reason}"
            ));
            return false;
        }
        if self.serial().is_empty() {
            self.log(format!("控制通道重启被跳过(未选择设备):{reason}"));
            return false;
        }
        self.log(format!(
            "正在重启控制通道:{reason}(端口 tcp:{LOCAL_PORT},旧 server 先关掉以腾干净 socket 名;连上后会按当前按键状态重建触点)"
        ));
        crate::diag_warn!("app", "重启控制通道: {reason}");
        // 旧结论作废:重连之后要重新自检,不能拿"上一条通道的死讯"当新通道的现状
        self.channel_dead_confirm.reset();
        self.channel_probe = None;
        self.channel_probed_at = None;
        // 手动/自检重启 = 用户还想要连接;退避计数清零,与[连接控制]同口径
        self.reconnect_attempts = 0;
        self.channel_restart_started = Some(Instant::now());
        self.connect_control();
        true
    }

    /// 手动**强制重连控制通道**(诊断面板按钮;以后接热键只需调这一句)。
    ///
