    /// 设备端读线程已经死了 —— 探针说"活",用户却什么都按不动。所以这条入口
    /// **不受自检结论限制**,随时可执行,重启之后能用就是最直接的判据。
    fn force_reconnect_control_channel(&mut self) {
        self.restart_control_channel("用户手动强制重连(只重启我们自己的控制通道,不影响 scrcpy 投屏)");
    }
